// Hesap kartının saf mantığı: tutar doğrulama, hareket süzme, grafik noktaları ve yazımlar. Para TRY'dir; hesap kuruş tamsayısıyla yapılır.
// Bileşen gerçek para hareketi yapmaz: ekrandaki doğrulama kolaylıktır, asıl denetim uygulamanın defterindedir.
import { date, math, money, text } from "@snn/abacus-core";
import { smoothLine, roundTo } from "../lib/chart-format";
import { exactText, signedMinorText, toMinor } from "../lib/shop-format";

export type WalletAction = "send" | "deposit" | "convert" | "receive";
export const ACTIONS: { value: WalletAction; label: string; verb: string }[] = [
  { value: "send", label: "Gönder", verb: "gönder" },
  { value: "deposit", label: "Yatır", verb: "yatır" },
  { value: "convert", label: "Çevir", verb: "çevir" },
  { value: "receive", label: "Al", verb: "iste" },
];
/** Bakiyeden düşen işlemler: tutar bakiyeyi aşamaz. */
export const spends = (action: WalletAction): boolean => action === "send" || action === "convert";

export interface WalletTransaction {
  id: string;
  title: string;
  /** İşlem günü, ISO tarih ("2026-10-14"). */
  date: string;
  /** Kaynak ya da kişi ("Kasa", "Barış Yıldız"). */
  source?: string;
  /** Ana birimde TRY; çıkan eksi. */
  amount: number;
}
export interface BalancePoint { /** ISO tarih. */ date: string; /** Ana birimde TRY. */ value: number }
export interface WalletAccount {
  id: string;
  label: string;
  balance: number;
  /** Bu ay değişim (ana birimde TRY, işaretli). */
  monthChange: number;
  /** Dönem anahtarı → bakiye noktaları (eskiden yeniye). */
  history: Record<string, BalancePoint[]>;
  transactions: WalletTransaction[];
}

export interface AmountResult { minor: number | null; error: string | null }

/** Yazılan tutarı doğrular: boş, sıfır ya da negatif, en çok iki ondalık, harcamada bakiyeyi aşma. */
export function checkAmount(raw: string, action: WalletAction, balanceMinor: number): AmountResult {
  if (!raw.trim()) return { minor: null, error: "Tutarı girin." };
  const value = money.parseNumber(raw.trim());
  if (value === null || !Number.isFinite(value)) return { minor: null, error: "Geçerli bir tutar girin." };
  if (value <= 0) return { minor: null, error: "Tutar sıfırdan büyük olmalı." };
  const minor = toMinor(value);
  if (math.abs(math.sub(value, math.div(minor, 100) ?? 0)) > 1e-9) return { minor: null, error: "En çok iki ondalık yazılabilir." };
  if (spends(action) && minor > balanceMinor) return { minor: null, error: "Tutar bakiyenizi aşıyor." };
  return { minor, error: null };
}

/** Hareketleri başlık, kaynak ve tarih metninde arar (Türkçe büyük/küçük harf duyarsız). */
export function filterTransactions(list: WalletTransaction[], query: string): WalletTransaction[] {
  const needle = text.lower(query.trim());
  if (!needle) return list;
  return list.filter(item => text.lower(`${item.title} ${item.source ?? ""} ${date.format(item.date, "short")}`).includes(needle));
}

/** Grafik noktalarını `width` × `height` kutusuna yerleştirir; yol yumuşak çizgidir. Tek nokta düz çizgi olur. */
export function chartGeometry(points: BalancePoint[], width = 300, height = 84, pad = 6) {
  if (!points.length) return { line: "", area: "", dots: [] as { x: number; y: number }[] };
  const values = points.map(point => point.value);
  const low = Math.min(...values), high = Math.max(...values), span = high - low || 1;
  const dots = points.map((point, at) => ({ x: roundTo(points.length === 1 ? width / 2 : (at / (points.length - 1)) * width, 2), y: roundTo(pad + (1 - (point.value - low) / span) * (height - 2 * pad), 2) }));
  const line = smoothLine(dots);
  const last = dots[dots.length - 1]!, first = dots[0]!;
  return { line, area: `${line}L${last.x} ${height}L${first.x} ${height}Z`, dots };
}

export const balanceText = (balance: number): string => exactText(toMinor(balance));
export const changeText = (monthChange: number): string => `${signedMinorText(toMinor(monthChange))} bu ay`;
export const pointText = (point: BalancePoint): string => `${date.format(point.date, "long")}: ${balanceText(point.value)}`;
export const transactionAmountText = (amount: number): string => signedMinorText(toMinor(amount));
export const transactionMeta = (item: WalletTransaction): string => item.source ? `${date.format(item.date, "short")} · ${item.source}` : date.format(item.date, "short");
export const submitLabel = (action: WalletAction, minor: number | null): string => {
  const found = ACTIONS.find(item => item.value === action)!;
  return minor === null ? found.label : action === "deposit" ? `${exactText(minor)} ekle` : action === "receive" ? `${exactText(minor)} iste` : `${exactText(minor)} ${found.verb}`;
};

.root { container-type: inline-size; display: grid; gap: var(--space-4); width: 100%; max-width: 660px; box-sizing: border-box; padding: var(--space-6); border: 1px solid var(--border); border-radius: var(--radius-panel); background: var(--surface); color: var(--foreground); }
.top { display: flex; align-items: center; justify-content: space-between; gap: var(--space-3); }
.eye { display: grid; place-items: center; width: 2.25rem; height: 2.25rem; border: 1px solid var(--border); border-radius: 50%; background: var(--surface); color: var(--text-secondary); cursor: pointer; }
.eye:focus-visible, .action:focus-visible { outline: var(--focus-outline-width, 2px) solid var(--focus-outline, var(--accent)); outline-offset: 2px; }
.balance { display: grid; gap: 2px; }
.balance p { margin: 0; }
.label { color: var(--text-secondary); font-size: var(--text-sm); }
.amount { font-family: var(--font-display); font-size: var(--text-5xl); font-weight: 500; letter-spacing: var(--tracking-display); line-height: 1.1; font-variant-numeric: tabular-nums; }
.mask { letter-spacing: .1em; color: var(--text-muted); }
.change { min-height: 1.2rem; color: var(--text-secondary); font-size: var(--text-sm); font-variant-numeric: tabular-nums; }
.periodRow { display: flex; }
.chart { display: grid; gap: var(--space-1); }
.readout { min-height: 1.2rem; margin: 0; color: var(--text-secondary); font-size: var(--text-xs); font-variant-numeric: tabular-nums; }
.plot { position: relative; height: 5.25rem; border-radius: var(--radius-control); }
.plot:focus-within { outline: var(--focus-outline-width, 2px) solid var(--focus-outline, var(--accent)); outline-offset: 2px; }
.plot svg { width: 100%; height: 100%; overflow: visible; }
.area { fill: var(--accent-subtle); opacity: .6; }
.line { fill: none; stroke: var(--accent); stroke-width: 2; vector-effect: non-scaling-stroke; }
.marker { position: absolute; width: .7rem; height: .7rem; margin: -.35rem 0 0 -.35rem; border: 2px solid var(--accent); border-radius: 50%; background: var(--surface); pointer-events: none; transition: left var(--duration-fast, .16s), top var(--duration-fast, .16s); }
.scrub { position: absolute; inset: 0; width: 100%; height: 100%; margin: 0; opacity: 0; cursor: crosshair; }
.actions { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: var(--space-2); }
.action { min-height: 2.5rem; border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface); color: var(--foreground); font: inherit; font-size: var(--text-sm); cursor: pointer; }
.action[aria-pressed="true"] { border-color: var(--foreground); background: var(--foreground); color: var(--background); }
.panel { display: grid; gap: var(--space-2); padding: var(--space-4); border-radius: var(--radius-control); background: var(--surface-muted); }
.fieldLabel { color: var(--text-secondary); font-size: var(--text-xs); }
.money { position: relative; }
.money i { position: absolute; top: 50%; left: var(--space-3); transform: translateY(-50%); color: var(--text-muted); font-style: normal; }
.money input { width: 100%; box-sizing: border-box; min-height: 2.75rem; padding: 0 var(--space-3) 0 var(--space-6); border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface); color: var(--foreground); font: inherit; font-size: var(--text-lg); font-variant-numeric: tabular-nums; }
.money input:focus-visible { outline: var(--focus-outline-width, 2px) solid var(--focus-outline, var(--accent)); outline-offset: 1px; }
.money input[aria-invalid="true"] { border-color: var(--danger); }
.error { margin: 0; color: var(--danger); font-size: var(--text-xs); }
.hint { margin: 0; color: var(--text-muted); font-size: var(--text-xs); }
.history { display: grid; gap: var(--space-3); }
.historyHead { display: flex; align-items: center; justify-content: space-between; }
.historyHead h3 { margin: 0; font-size: var(--text-sm); font-weight: 500; }
.list { display: grid; margin: 0; padding: 0; list-style: none; }
.tx { display: grid; grid-template-columns: 2rem minmax(0, 1fr) auto; gap: var(--space-3); align-items: center; overflow: hidden; padding: var(--space-2) 0; border-bottom: 1px solid var(--border-subtle); }
.txIcon { display: grid; place-items: center; width: 2rem; height: 2rem; border-radius: 50%; background: var(--surface-muted); color: var(--text-secondary); font-size: var(--text-sm); }
.txText { display: grid; min-width: 0; font-size: var(--text-sm); }
.txText b { font-weight: 500; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.txText span { color: var(--text-muted); font-size: var(--text-xs); }
.txAmount { font-size: var(--text-sm); font-variant-numeric: tabular-nums; }
.txAmount[data-out] { color: var(--foreground); }
.muted { margin: 0; color: var(--text-muted); font-size: var(--text-sm); }
.skeleton { display: grid; gap: var(--space-3); }
.skeleton span { display: block; height: 2rem; border-radius: var(--radius-control); background: var(--neutral-3); animation: pulse 1.4s ease-in-out infinite; }
.skeleton span:nth-child(2) { height: 5rem; }
@keyframes pulse { 50% { opacity: .5; } }
.root[data-reduced] .skeleton span, .root[data-reduced] .marker { animation: none; transition: none; }
@media (prefers-reduced-motion: reduce) { .skeleton span { animation: none; } .marker { transition: none; } }
@container (max-width: 420px) { .root { padding: var(--space-4); } .amount { font-size: var(--text-4xl); } }
@container (max-width: 280px) { .actions { grid-template-columns: repeat(2, minmax(0, 1fr)); } .amount { font-size: var(--text-3xl); } }

"use client";

import { useEffect, useId, useMemo, useRef, useState } from "react";
import { AnimatePresence, motion } from "motion/react";
import { AnimatedCounter } from "../animated-counter/animated-counter";
import { Button } from "../button/button";
import { DropdownMenu } from "../dropdown-menu/dropdown-menu";
import { EmptyState } from "../empty-state/empty-state";
import { SearchField } from "../search-field/search-field";
import SegmentedControl from "../segmented-control/segmented-control";
import { motionTokens } from "../lib/motion-tokens";
import { srOnly, useAnnouncer } from "../lib/shop-parts";
import { toMinor } from "../lib/shop-format";
import { money } from "@snn/abacus-core";
import { useReducedMotionSafe } from "../lib/viz-utils";
import { ACTIONS, balanceText, changeText, chartGeometry, checkAmount, filterTransactions, pointText, spends, submitLabel, transactionAmountText, transactionMeta, type BalancePoint, type WalletAccount, type WalletAction, type WalletTransaction } from "./wallet-card-format";
import styles from "./wallet-card.module.css";

export type { BalancePoint, WalletAccount, WalletAction, WalletTransaction };

/** Küçük bir hesap görünümü için kullanın: bakiye, bakiye geçmişi grafiği, son hareketler ve odaklı para işlemleri (gönder, yatır, çevir, al). Gerçek para hareketi yapmaz: işlemi `onSubmit` ile uygulamanın defterine bağlayın; istemcideki tutar doğrulaması kolaylıktır, asıl denetim sunucudadır. Fatura ve abonelik için değil. */
export interface WalletCardProps {
  accounts: WalletAccount[];
  /** Dönem düğmeleri; `value` her hesabın `history` anahtarıdır. */
  periods: { value: string; label: string }[];
  defaultAccount?: string;
  /** İşlemi defterde yapar; reddederse hata iletisi yazılır. Hesapları güncelleyip yeni `accounts` verin: bakiye yeni değere sayar, yeni hareket yerinde açılır. */
  onSubmit: (order: { account: string; action: WalletAction; amountMinor: number }) => Promise<void>;
  onViewAll?: () => void;
  loading?: boolean;
}

function BalanceChart({ points, label }: { points: BalancePoint[]; label: string }) {
  const [active, setActive] = useState<number | null>(null);
  const shape = useMemo(() => chartGeometry(points), [points]);
  const shown = points[active ?? points.length - 1];
  const dot = shape.dots[active ?? shape.dots.length - 1];
  if (!points.length || !shown || !dot) return <p className={styles.muted}>Bu dönemde veri yok.</p>;
  return <div className={styles.chart}>
    <p className={styles.readout} aria-hidden="true">{pointText(shown)}</p>
    <div className={styles.plot} data-focus={active !== null || undefined}>
      <svg viewBox="0 0 300 84" preserveAspectRatio="none" aria-hidden="true"><path className={styles.area} d={shape.area} /><motion.path className={styles.line} d={shape.line} initial={false} animate={{ d: shape.line }} transition={{ duration: motionTokens.duration.standard }} /></svg>
      <span className={styles.marker} style={{ left: `${(dot.x / 300) * 100}%`, top: `${(dot.y / 84) * 100}%` }} aria-hidden="true" />
      <input type="range" className={styles.scrub} min={0} max={points.length - 1} step={1} value={active ?? points.length - 1} aria-label={label} aria-valuetext={pointText(shown)}
        onChange={event => setActive(Number(event.target.value))} onPointerLeave={() => setActive(null)} onBlur={() => setActive(null)} />
    </div>
  </div>;
}

export function WalletCard({ accounts, periods, defaultAccount, onSubmit, onViewAll, loading = false }: WalletCardProps) {
  const reduced = useReducedMotionSafe();
  const uid = useId();
  const [accountId, setAccountId] = useState(defaultAccount ?? accounts[0]?.id ?? "");
  const [period, setPeriod] = useState(periods[1]?.value ?? periods[0]?.value ?? "");
  const [hidden, setHidden] = useState(false);
  const [action, setAction] = useState<WalletAction | null>(null);
  const [raw, setRaw] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [query, setQuery] = useState("");
  const [all, setAll] = useState(false);
  const [live, announce] = useAnnouncer();
  const actionButtons = useRef<Record<string, HTMLButtonElement | null>>({});
  const account = accounts.find(item => item.id === accountId) ?? accounts[0];
  const balanceMinor = account ? toMinor(account.balance) : 0;
  const found = useMemo(() => filterTransactions(account?.transactions ?? [], query), [account, query]);
  const rows = all ? found : found.slice(0, 3);
  const step = reduced ? { duration: 0 } : motionTokens.spring.smooth;
  const check = action ? checkAmount(raw, action, balanceMinor) : null;

  useEffect(() => { setError(null); }, [raw, action]);

  if (loading || !account) return <div className={styles.root} aria-busy="true" role="status" aria-label="Hesap yükleniyor"><div className={styles.skeleton}><span /><span /><span /></div></div>;

  const submit = async () => {
    if (!action || busy) return;
    const result = checkAmount(raw, action, balanceMinor);
    if (result.error || result.minor === null) { setError(result.error); return; }
    setBusy(true);
    try {
      await onSubmit({ account: account.id, action, amountMinor: result.minor });
      announce(`${ACTIONS.find(item => item.value === action)!.label} işlemi tamamlandı.`);
      const finished = action;
      setAction(null); setRaw("");
      requestAnimationFrame(() => actionButtons.current[finished]?.focus());
    } catch { setError("İşlem tamamlanamadı. Tekrar deneyin."); }
    finally { setBusy(false); }
  };

  return <motion.section layout={!reduced} transition={step} className={styles.root} aria-label="Hesap özeti" data-reduced={reduced || undefined}>
    <header className={styles.top}>
      <DropdownMenu label={account.label} items={accounts.map(item => ({ label: item.label, onSelect: () => { setAccountId(item.id); setAll(false); setQuery(""); } }))} />
      <button type="button" className={styles.eye} aria-pressed={hidden} aria-label={hidden ? "Bakiyeyi göster" : "Bakiyeyi gizle"} onClick={() => setHidden(!hidden)}>
        <svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="M2 12s3.5-6.5 10-6.5S22 12 22 12s-3.5 6.5-10 6.5S2 12 2 12z" /><circle cx="12" cy="12" r="3" />{hidden && <path d="M4 4l16 16" />}</svg>
      </button>
    </header>

    <div className={styles.balance} role="status" aria-live="polite" aria-atomic="true">
      <p className={styles.label}>Kullanılabilir bakiye</p>
      <span className={srOnly}>{hidden ? "Bakiye gizli" : balanceText(account.balance)}</span>
      <p className={styles.amount} aria-hidden="true">{hidden ? <span className={styles.mask}>₺ ••••••</span> : <AnimatedCounter value={account.balance} decimals={2} prefix="₺" />}</p>
      <p className={styles.change} aria-hidden={hidden || undefined}>{hidden ? "" : changeText(account.monthChange)}</p>
    </div>

    <div className={styles.periodRow}><SegmentedControl label="Dönem" options={periods} value={period} onValueChange={setPeriod} /></div>
    <BalanceChart points={account.history[period] ?? []} label="Bakiye geçmişi: noktaları gezmek için ok tuşları" />

    <div className={styles.actions} role="group" aria-label="İşlemler">
      {ACTIONS.map(item => <button key={item.value} ref={node => { actionButtons.current[item.value] = node; }} type="button" className={styles.action} aria-pressed={action === item.value} aria-controls={`${uid}-panel`} onClick={() => { setAction(action === item.value ? null : item.value); setRaw(""); }}>{item.label}</button>)}
    </div>
    <AnimatePresence initial={false} mode="wait">
      {action && <motion.form key={action} id={`${uid}-panel`} className={styles.panel} noValidate
        initial={reduced ? false : { opacity: 0, y: 8, filter: "blur(3px)" }} animate={{ opacity: 1, y: 0, filter: "blur(0px)" }} exit={{ opacity: 0 }} transition={reduced ? { duration: 0 } : { duration: motionTokens.duration.fast }}
        onSubmit={event => { event.preventDefault(); void submit(); }}>
        <label htmlFor={`${uid}-amount`} className={styles.fieldLabel}>Tutar</label>
        <div className={styles.money}><i aria-hidden="true">₺</i>
          <input id={`${uid}-amount`} inputMode="decimal" autoComplete="off" autoFocus value={raw} placeholder="0,00" aria-invalid={!!error || undefined} aria-describedby={error ? `${uid}-error` : undefined}
            onChange={event => setRaw(money.formatGroupedInput(event.target.value, { maxDigits: 2 }))} /></div>
        {error && <p id={`${uid}-error`} className={styles.error} role="alert">{error}</p>}
        {spends(action) && <p className={styles.hint}>Kullanılabilir: {balanceText(account.balance)}</p>}
        <Button type="submit" variant="primary" loading={busy} aria-busy={busy}>{submitLabel(action, check?.minor ?? null)}</Button>
      </motion.form>}
    </AnimatePresence>

    <section className={styles.history} aria-label="Son hareketler">
      <div className={styles.historyHead}><h3>Son hareketler</h3>{found.length > 3 && <Button size="sm" variant="ghost" onClick={() => { setAll(!all); onViewAll?.(); }}>{all ? "Daha az" : "Tümünü gör"}</Button>}</div>
      {account.transactions.length > 0 && <SearchField label="Hareketlerde ara" value={query} onValueChange={setQuery} placeholder="Hareketlerde ara" />}
      {account.transactions.length === 0 ? <p className={styles.muted}>Henüz hareket yok</p>
        : found.length === 0 ? <EmptyState title="Sonuç yok" description="Bu aramaya uyan hareket bulunamadı." />
        : <ul className={styles.list}><AnimatePresence initial={false}>{rows.map(item => <motion.li key={item.id} layout={!reduced} className={styles.tx} initial={reduced ? false : { opacity: 0, height: 0 }} animate={{ opacity: 1, height: "auto" }} exit={{ opacity: 0, height: 0 }} transition={step}>
          <span className={styles.txIcon} aria-hidden="true">{item.amount < 0 ? "↗" : "↙"}</span>
          <span className={styles.txText}><b>{item.title}</b><span>{transactionMeta(item)}</span></span>
          <span className={styles.txAmount} data-out={item.amount < 0 || undefined}>{hidden ? "••••" : transactionAmountText(item.amount)}</span>
        </motion.li>)}</AnimatePresence></ul>}
    </section>
    {live}
  </motion.section>;
}

export default WalletCard;
